class TinyLRU:
    def __init__(self, cap):
        self.cap = cap
        self.data = {}

    def get(self, key):
        if key not in self.data:
            return None
        value = self.data.pop(key)
        self.data[key] = value
        return value

    def put(self, key, value):
        if key in self.data:
            self.data.pop(key)
        elif len(self.data) >= self.cap:
            oldest = next(iter(self.data))
            self.data.pop(oldest)
        self.data[key] = value

