def groups(graph):
    seen = set()

    def walk(node):
        seen.add(node)
        for nxt in graph.get(node, []):
            if nxt not in seen:
                walk(nxt)

    count = 0
    for node in graph:
        if node not in seen:
            walk(node)
            count += 1
    return count

